With every recommendation and song record available, artist appearances can be counted from real data and the unique highest-frequency artist ID can be selected without hardcoded IDs or counts.

```python
artist_recommendation_counts = {}
artist_names_from_songs = {}
artist_first_positions = {}
for recommendation_index, recommendation in enumerate(recommendations):
    song = recommended_songs_by_id[recommendation["song_id"]]
    artist_ids_seen_in_song = set()
    for artist in song["artists"]:
        artist_id = artist["id"]
        if artist_id in artist_ids_seen_in_song:
            continue
        artist_ids_seen_in_song.add(artist_id)
        artist_recommendation_counts[artist_id] = artist_recommendation_counts.get(artist_id, 0) + 1
        artist_names_from_songs[artist_id] = artist["name"]
        if artist_id not in artist_first_positions:
            artist_first_positions[artist_id] = recommendation_index
if not artist_recommendation_counts:
    raise RuntimeError("No artists were present in the recommendations")
maximum_recommendation_count = max(artist_recommendation_counts.values())
top_artist_ids = [artist_id for artist_id, count in artist_recommendation_counts.items() if count == maximum_recommendation_count]
artist_candidate_summary = sorted(
    [
        {
            "artist_id": artist_id,
            "name": artist_names_from_songs[artist_id],
            "recommendation_count": count,
            "first_recommendation_index": artist_first_positions[artist_id],
        }
        for artist_id, count in artist_recommendation_counts.items()
    ],
    key=lambda item: (-item["recommendation_count"], item["first_recommendation_index"], item["artist_id"]),
)
print(artist_candidate_summary)
if len(top_artist_ids) != 1:
    raise RuntimeError("The most-recommended artist is not unique")
most_recommended_artist_id = top_artist_ids[0]
```

